// Operations views: canonical queue, incidents, alerts and station inventory/notes/references.
// Ordering always comes from the server's canonical priority engine (web/lib/fleet/priority.mjs).
import {TIERS,formatDuration} from './lib/fleet/priority.mjs';
import {WORKFLOW_STATES} from './lib/fleet/engine.mjs';
import {localToUtc} from './lib/fleet/time.mjs';
const detroit=(local,time)=>new Date(localToUtc(local,time).ms).toISOString();
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=v=>v&&Number.isFinite(Date.parse(v))?new Date(v).toLocaleString('en-US',{timeZone:'America/Detroit',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})+' ET':'—';
const num=v=>typeof v==='number'&&Number.isFinite(v)?Number(v.toFixed(2)).toLocaleString():'—';
const TIER_ICON={P1:'◆◆',P2:'◆',P3:'▲▲',P4:'▲',QC:'?',PM:'●',FEED:'!'};
export const TIER_COLORS={P1:'#8f1d2c',P2:'#c0392b',P3:'#b8661b',P4:'#a68a1a',QC:'#6b5b95',PM:'#4a6d8c'};
export function tierPill(tier,{confidence}={}){return `<span class="tier tier-${esc(tier)}" title="${esc(TIERS[tier]?.description||tier)}"><b aria-hidden="true">${TIER_ICON[tier]||''}</b>${esc(tier)} · ${esc(TIERS[tier]?.label||tier)}${confidence&&confidence!=='confirmed'?' · suspected':''}</span>`;}
const STATE_LABEL={new:'New',acknowledged:'Acknowledged',investigating:'Investigating',planned:'Planned',in_progress:'In progress',awaiting_parts:'Awaiting parts',awaiting_access:'Awaiting access',monitoring:'Monitoring recovery',resolved:'Resolved',merged:'Merged'};
const CHANNEL_STATE={ok:['reporting','Reporting'],silent:['stale','Not reporting'],missing:['stale','Missing'],stale:['stale','Stale'],'null-value':['stale','Null value'],'qc-suspect':['qc','QC suspect'],'not-expected':['unknown','Not expected'],future:['clock','Future time'],'possible-rename':['delayed','Possible rename']};
const REPORTING={reporting:['reporting','Reporting'],delayed:['delayed','Delayed'],'outage-candidate':['stale','Not reporting'],'no-data':['unknown','No data'],'not-in-response':['unknown','Missing from response'],inactive:['inactive','Inactive'],maintenance:['unknown','Planned maintenance'],clock:['clock','Clock ahead']};
let filters={search:'',tier:'all',region:'all',owner:'all',status:'all'},expanded=new Set(),selectedItem=null,mapApi=null;
let incident={id:null,data:null,error:'',loading:false,form:null},station={id:null,data:null,error:'',loading:false},alerts={data:null,loading:false,error:''};
export function resetOps(){filters={search:'',tier:'all',region:'all',owner:'all',status:'all'};expanded=new Set();selectedItem=null;mapApi=null;incident={id:null,data:null,error:'',loading:false,form:null};station={id:null,data:null,error:'',loading:false};alerts={data:null,loading:false,error:''};}

// ---------- feed health and counts ----------
export function feedBanner(ops,state){
 if(!ops)return '';
 const f=ops.feed,parts=[];
 if(f.status==='failed')parts.push(`<div class="alert error" role="alert"><strong>Weather data feed problem.</strong> ${esc((f.reasons||[]).join(' ')||'The last refresh failed.')} Showing the snapshot fetched ${date(f.networkFetchedAt)}. Station outages are not confirmed from missing feed data.</div>`);
 else if(f.status==='degraded')parts.push(`<div class="alert" role="alert"><strong>Provider snapshot incomplete.</strong> ${esc((f.reasons||[]).join(' '))} Outage confirmation is held; existing incidents stay visible.</div>`);
 else if(f.status==='stale')parts.push(`<div class="alert">Network data is ${f.cacheAgeMinutes} minutes old (fetched ${date(f.networkFetchedAt)}).</div>`);
 if(state?.assessmentError)parts.push(`<div class="alert">${esc(state.assessmentError.message)}</div>`);
 return parts.join('');
}
function countCard(tier,value,hint,klass=''){return `<button class="metric tiercount ${klass}" data-tier-filter="${tier}" aria-label="Show ${esc(TIERS[tier]?.label||tier)} items"><span class="label">${tierPill(tier)}</span><div class="value">${value}</div><div class="hint">${hint}</div></button>`;}
export function countRow(ops){
 const c=ops.counts;
 return `<div class="metrics tiermetrics">${countCard('P1',c.P1,`${c.P1Stations} station${c.P1Stations===1?'':'s'} in groups`,c.P1?'urgent':'')}${countCard('P2',c.P2,'Single stations fully out',c.P2?'urgent':'')}${countCard('P3',c.P3,'Reporting, several sensors down')}${countCard('P4',c.P4,'Reporting, one sensor down')}</div>
 <p class="statusline"><strong>${c.stationsAffected}</strong> stations affected · ${c.suspected} suspected (awaiting confirmation) · ${c.unassigned} unassigned · ${c.overdue} past provisional deadline · ${c.QC} QC reviews · ${c.PM} maintenance. <span class="text-muted">${esc(ops.countNote)}</span></p>`;
}

// ---------- queue ----------
function visible(ops){
 const q=filters.search.toLowerCase();
 return ops.queue.filter(i=>(filters.tier==='all'||i.effectiveTier===filters.tier)&&(filters.region==='all'||i.regions.includes(filters.region))&&(filters.owner==='all'||(filters.owner==='unassigned'?!i.assignee:i.assignee===filters.owner))&&(filters.status==='all'||filters.status==='suspected'&&i.confidence!=='confirmed'||filters.status===i.state||filters.status==='overdue'&&i.overdue)&&(!q||`${i.title} ${i.stations.join(' ')} ${i.assignee||''}`.toLowerCase().includes(q)));
}
export function queueFilters(ops){
 const owners=[...new Set(ops.queue.map(i=>i.assignee).filter(Boolean))].sort();
 const sel=(id,label,opts,val)=>`<label for="${id}" class="sr-only">${label}</label><select id="${id}" data-queue-filter="${id.replace('qf-','')}">${opts.map(([v,t])=>`<option value="${esc(v)}" ${v===val?'selected':''}>${esc(t)}</option>`).join('')}</select>`;
 return `<div class="filters"><label class="sr-only" for="qf-search">Search queue</label><input id="qf-search" data-queue-filter="search" placeholder="Search station, group or owner…" value="${esc(filters.search)}">${sel('qf-tier','Tier',[['all','All tiers'],...Object.keys(TIERS).map(t=>[t,`${t} · ${TIERS[t].label}`])],filters.tier)}${sel('qf-region','Region',[['all','All regions'],...ops.regions.map(r=>[r,r])],filters.region)}${sel('qf-owner','Owner',[['all','Any owner'],['unassigned','Unassigned'],...owners.map(o=>[o,o])],filters.owner)}${sel('qf-status','Status',[['all','Any status'],['suspected','Suspected'],['overdue','Past deadline'],...WORKFLOW_STATES.filter(s=>s!=='resolved').map(s=>[s,STATE_LABEL[s]])],filters.status)}<span id="queue-count">${visible(ops).length} of ${ops.queue.length}</span></div>`;
}
function affected(i){
 if(i.scope==='group')return `${i.stations.length} stations`;
 if(i.kind==='outage')return 'All expected channels';
 if(i.sensorGroups.length)return `${i.channels.length} channel${i.channels.length===1?'':'s'} · ${i.sensorGroups.length} ${i.provisionalGrouping?'provisional ':''}instrument${i.sensorGroups.length===1?'':'s'}`;
 return '—';
}
function lastGood(i){return i.lastGood?`${date(i.lastGood)}<small>${formatDuration(i.durationMinutes)} ago${i.onset?.latest&&i.onset.latest!==i.lastGood?' · onset between last good and '+date(i.onset.latest):''}</small>`:'Unknown';}
function row(i,{child=false,compact=false}={}){
 const open=expanded.has(i.id),stateTxt=`${STATE_LABEL[i.state]||i.state}${i.telemetry==='recovering'?' · recovering':i.telemetry==='partial-recovery'?' · partial recovery':''}${i.feedHeld?' · held (feed)':''}`;
 const name=i.scope==='group'?`<button class="station-link" data-incident="${esc(i.id)}">${esc(i.title)}</button><small>${esc(i.stations.join(', '))}</small>`:i.scope==='review'||i.scope==='maintenance'?`<button class="station-link" data-station="${esc(i.station)}">${esc(i.title)}</button><small class="mono">${esc(i.station)}</small>`:`<button class="station-link" data-incident="${esc(i.id)}">${esc(i.title)}</button><small class="mono">${esc(i.station)}</small>`;
 const reason=esc(i.reasons[0]||'');
 return `<tr class="queue-row${child?' child':''}${selectedItem===i.id?' selected':''}" data-queue-item="${esc(i.id)}" data-stations="${esc(i.stations.join(','))}"><td>${child?'<span class="tree" aria-hidden="true">└</span>':''}${tierPill(i.effectiveTier,{confidence:i.confidence})}${i.tierOverride?'<small>Override: '+esc(i.tierOverride.reason)+'</small>':''}${i.overdue?'<small class="overdue">Past provisional deadline</small>':''}</td><td>${name}${i.scope==='group'&&!child?`<button class="small quiet expand" data-expand="${esc(i.id)}" aria-expanded="${open}">${open?'Hide':'Show'} members</button>`:''}</td><td><p class="review-reason">${reason}</p></td>${compact?'':`<td>${lastGood(i)}</td><td>${affected(i)}</td>`}<td>${esc(i.assignee||'Unassigned')}<small>${esc(stateTxt)}</small></td><td><p class="review-reason">${esc(i.nextAction)}</p><div class="rowactions">${i.stations.length?`<button class="small quiet" data-locate="${esc(i.id)}" aria-label="Show on map">Map</button>`:''}${i.scope==='station'||i.scope==='group'?`<button class="small" data-incident="${esc(i.id)}">Open</button>`:`<button class="small" data-station="${esc(i.station)}">Inspect</button>`}</div></td></tr>`+(i.scope==='group'&&open&&!child?(i.members||[]).map(m=>row(m,{child:true,compact})).join(''):'');
}
export function queueTable(ops,{compact=false,limit=null}={}){
 const items=visible(ops),shown=limit?items.slice(0,limit):items;
 if(!ops.queue.length)return `<div class="empty"><h2>${ops.feed.status==='ok'?'No open station or sensor incidents':'No incidents recorded'}</h2><p>${ops.feed.status==='ok'?'Every active station is reporting its expected channels in the latest snapshot.':'Waiting for a complete provider snapshot.'}</p></div>`;
 return `<div class="tablewrap"><table class="queue"><thead><tr><th>Tier</th><th>Station / group</th><th>Reason</th>${compact?'':'<th>Last good</th><th>Affected</th>'}<th>Owner · state</th><th>Next action</th></tr></thead><tbody id="queue-rows" data-limit="${limit||''}">${shown.map(i=>row(i,{compact})).join('')||`<tr><td colspan="7"><div class="empty">No items match these filters.</div></td></tr>`}</tbody></table></div>${limit&&items.length>limit?`<div class="panelbody"><button class="small quiet" data-nav="review">Show all ${items.length} in Daily review</button></div>`:''}`;
}
export function opsLegend(){return `<div class="mapfoot">${['P1','P2','P3','P4'].map(t=>`<span><i class="swatch" style="background:${TIER_COLORS[t]}"></i>${t} ${esc(TIERS[t].label)}</span>`).join('')}<span><i class="swatch" style="background:#648b53"></i>Reporting</span><span><i class="swatch" style="background:#cb9b43"></i>Delayed</span><span><i class="swatch" style="background:#b4bcb0"></i>Inactive</span></div>`;}
export function markerStyle(s,ops){
 const item=ops?.queue.find(i=>i.stations.includes(s.id)&&['P1','P2','P3','P4'].includes(i.effectiveTier)),h=ops?.health?.[s.id];
 if(item)return {fill:TIER_COLORS[item.effectiveTier],radius:item.effectiveTier==='P1'?8:item.effectiveTier==='P2'?7:6,label:`${item.effectiveTier} · ${item.title}`,item};
 if(s.archiveStatus==='INACTIVE')return {fill:'#b4bcb0',radius:3,label:'Inactive'};
 if(h?.reporting==='delayed')return {fill:'#cb9b43',radius:5,label:'Delayed'};
 return {fill:'#648b53',radius:5,label:'Reporting'};
}
// The map registers its markers so queue rows and markers can select each other.
export function registerMap(api){mapApi=api;}
export function selectFromMap(stationId,ops){const item=ops?.queue.find(i=>i.stations.includes(stationId));if(!item)return false;selectedItem=item.id;if(item.groupId)expanded.add(item.groupId);const rowEl=document.querySelector(`[data-queue-item="${CSS.escape(item.id)}"]`);document.querySelectorAll('.queue-row.selected').forEach(r=>r.classList.remove('selected'));if(rowEl){rowEl.classList.add('selected');rowEl.scrollIntoView({block:'nearest',behavior:'smooth'});}return true;}

// ---------- pages ----------
export function reviewPage({state,heading,busy,icon}){
 const ops=state.ops;if(!ops)return '<div class="empty">Operations data unavailable.</div>';
 return heading('Workspace','Daily review','Every open item in canonical priority order: P1 group outages, then single-station outages, then multiple and single missing sensors.',`<button class="primary" data-refresh ${busy?'disabled':''}>${icon('refresh')} Refresh network</button>`)+feedBanner(ops,state)+countRow(ops)+`<section class="panel"><div class="panelhead"><div><h2>Work queue</h2><p>Priority ${esc(ops.versions.priority)} · ${esc(ops.versions.engine)} · network fetched ${date(ops.feed.networkFetchedAt)}</p></div><button class="small" id="download-queue">Download queue</button></div>${queueFilters(ops)}${queueTable(ops)}</section>${tieBreakers(ops)}`;
}
function tieBreakers(ops){return `<details class="note"><summary>How the queue is ordered</summary><p class="footnote">Lexicographic, never a blended score: ${ops.tieBreakers.map((t,i)=>`${i+1}. ${esc(t)}`).join(' ')}</p><p class="footnote">${esc(ops.detection.note)}</p><p class="footnote">Grouping: stations within ${ops.grouping.linkKm} km and ${ops.grouping.onsetWindowMinutes} minutes of onset link; a group never spans more than ${ops.grouping.maxDiameterKm} km. ${esc(ops.grouping.rationale)}</p></details>`;}
export function alertsPage({heading}){
 if(!alerts.data&&!alerts.loading)queueMicrotask(loadAlerts);
 const list=alerts.data?.alerts||[];
 return heading('Workspace','Alerts','In-app alerts for confirmed incidents, escalations, recoveries and feed problems. Email, Teams and push delivery are not configured.')+`<section class="panel"><div class="panelhead"><div><h2>Unacknowledged</h2><p>${alerts.loading?'Loading…':list.length+' alert'+(list.length===1?'':'s')}</p></div>${list.length?'<button class="small" id="ack-all">Acknowledge shown</button>':''}</div>${alerts.error?`<div class="alert error">${esc(alerts.error)}</div>`:''}${list.map(a=>`<div class="queueitem"><div class="queueicon">${esc(TIER_ICON[a.tier]||'!')}</div><div class="grow"><div class="name">${a.tier?tierPill(a.tier):''} ${esc(a.title)}</div><p>${esc(a.detail)}</p><p>${date(a.created)} · ${esc(a.kind)}</p></div>${a.incidentId?`<button class="small" data-incident="${esc(a.incidentId)}">Open</button>`:''}<button class="small quiet" data-ack="${esc(a.id)}">Acknowledge</button></div>`).join('')||(!alerts.loading?'<div class="empty">No unacknowledged alerts.</div>':'')}</section><p class="footnote">Acknowledging an alert records that it was seen; it does not acknowledge or resolve the incident.</p>`;
}
let rerender=()=>{},api=null,toast=()=>{},currentUser=null;
// Called before every render so page builders can fetch even on a direct deep link.
export function configureOps(ctx){({api,toast,rerender}=ctx);currentUser=ctx.state.user;}
async function loadAlerts(){alerts.loading=true;try{alerts.data=await api('ops/alerts');alerts.error='';}catch(e){alerts.error=e.message;}finally{alerts.loading=false;rerender();}}

export function incidentPage({heading,selectedIncident,state}){
 if(incident.id!==selectedIncident){incident={id:selectedIncident,data:null,error:'',loading:false,form:null};}
 if(!incident.data&&!incident.loading&&!incident.error)queueMicrotask(loadIncident);
 if(!incident.data&&!incident.error)return '<div class="empty">Loading incident…</div>';
 if(incident.error&&!incident.data)return `<button class="back" data-nav="review">← Daily review</button><div class="alert error">${esc(incident.error)}</div>`;
 const {incident:i,events,work,members,suggestedTemplates}=incident.data,canEdit=currentUser?.role!=='viewer',f=incident.form||{};
 const stations=i.scope==='group'?(i.body.stations||[]):i.station?[i.station]:[];
 const ev=i.body.evidence;
 const header=heading('Incident',esc(i.body.title||'Incident'),`${tierPill(i.effectiveTier,{confidence:i.confidence})} <span class="pill">${esc(STATE_LABEL[i.state]||i.state)}</span> <span class="pill ${i.telemetry==='down'?'stale':i.telemetry==='recovered'?'reporting':'delayed'}">Telemetry ${esc(i.telemetry)}</span>`,`${stations.length===1?`<button data-station="${esc(stations[0])}">Inspect station</button>`:''}${i.scope!=='feed'&&canEdit?`<button class="primary" data-plan-stations="${esc(stations.join(','))}">Plan a visit</button>`:''}`);
 const reasons=`<section class="panel"><div class="panelhead"><h2>Why this priority</h2></div><div class="panelbody"><ul class="plain">${i.priorityReasons.map(r=>`<li>${esc(r)}</li>`).join('')}</ul>${(i.body.reasons||[]).map(r=>`<p>${esc(r)}</p>`).join('')}<dl class="definition"><dt>Last good report</dt><dd>${date(i.lastGood)}</dd><dt>Onset window</dt><dd>${i.body.onset?`Between ${date(i.body.onset.earliest)} and ${date(i.body.onset.latest)} (polling cannot pin it closer)`:'Unknown'}</dd><dt>First suspected</dt><dd>${date(i.firstSuspected)}</dd><dt>First confirmed</dt><dd>${date(i.firstConfirmed)}</dd><dt>Last assessed</dt><dd>${date(i.lastAssessed)}</dd>${i.recoveredAt?`<dt>Recovered</dt><dd>${date(i.recoveredAt)}</dd>`:''}${i.resolution?`<dt>Resolution</dt><dd>${esc(i.resolution)}</dd>`:''}<dt>Algorithm</dt><dd class="mono">${esc(i.algorithm)}</dd></dl>${i.body.feedHeld?'<p class="qc-note">The latest provider snapshot was incomplete, so confirmation counters are held.</p>':''}</div></section>`;
 const evidence=ev?`<section class="panel"><div class="panelhead"><div><h2>Latest evidence</h2><p>Snapshot ${date(ev.retrievedAt)} · feed ${esc(ev.feedQuality)} · ${ev.reportingCount}/${ev.expectedCount} expected channels reporting</p></div></div><div class="tablewrap"><table><thead><tr><th>Channel</th><th>State</th><th>Last observation</th></tr></thead><tbody>${(ev.affected||[]).map(c=>`<tr><td class="mono">${esc(c.channel)}</td><td>${channelPill(c.state)}</td><td>${date(c.time)}</td></tr>`).join('')||'<tr><td colspan="3">No channel detail.</td></tr>'}</tbody></table></div>${(i.body.sensorGroups||[]).length?`<div class="panelbody">${i.body.sensorGroups.map(g=>`<p><strong>${esc(g.label)}</strong>${g.provisional?' <span class="pill">provisional grouping</span>':''}: ${esc(g.channels.join(', '))}</p>`).join('')}</div>`:''}</section>`:'';
 const group=i.scope==='group'?groupPanel(i,members,canEdit,state):'';
 const form=canEdit&&i.scope!=='feed'?`<section class="panel"><div class="panelhead"><div><h2>Update</h2><p>Acknowledging records ownership; it does not resolve the incident.</p></div></div><form id="incident-form" class="panelbody"><div class="formgrid"><div class="field"><label for="inc-assignee">Owner</label><input id="inc-assignee" name="assignee" maxlength="100" value="${esc(f.assignee??i.assignee??'')}" list="team-names"></div><div class="field"><label for="inc-state">State</label><select id="inc-state" name="state">${WORKFLOW_STATES.map(s=>`<option value="${s}" ${(f.state??i.state)===s?'selected':''}>${STATE_LABEL[s]}</option>`).join('')}</select></div><div class="field wide" id="resolution-field" ${(f.state??i.state)==='resolved'&&i.state!=='resolved'?'':'hidden'}><label for="inc-resolution">Why resolved (telemetry recovery resolves automatically)</label><input id="inc-resolution" name="resolutionReason" maxlength="300" value="${esc(f.resolutionReason||'')}"></div><div class="field"><label for="inc-tier">Urgency override</label><select id="inc-tier" name="tier"><option value="">Computed (${esc(i.tier)})</option>${Object.keys(TIERS).map(t=>`<option value="${t}" ${(f.tier??i.tierOverride?.tier)===t?'selected':''}>${t} · ${esc(TIERS[t].label)}</option>`).join('')}</select></div><div class="field"><label for="inc-tier-reason">Override reason</label><input id="inc-tier-reason" name="tierReason" maxlength="500" value="${esc(f.tierReason??i.tierOverride?.reason??'')}"></div><div class="field"><label for="inc-defer">Defer until</label><input id="inc-defer" name="deferUntil" type="date" value="${esc(f.deferUntil??(i.deferral?.until||'').slice(0,10))}"></div><div class="field"><label for="inc-defer-reason">Deferral reason</label><input id="inc-defer-reason" name="deferReason" maxlength="500" value="${esc(f.deferReason??i.deferral?.reason??'')}"></div><div class="field wide"><label for="inc-note">Note for the timeline</label><textarea id="inc-note" name="note" maxlength="2000">${esc(f.note||'')}</textarea></div></div><div class="actions">${!i.acknowledgedAt?'<button type="button" id="inc-ack">Acknowledge</button>':`<span class="text-muted">Acknowledged by ${esc(i.acknowledgedBy)} ${date(i.acknowledgedAt)}</span>`}<button class="primary" type="submit">Save update</button></div><p id="incident-message" role="status" class="footnote">${esc(incident.error||'')}</p></form></section>`:'';
 const workPanel=`<section class="panel"><div class="panelhead"><div><h2>Work items</h2><p>Proposed tasks are prompts, not procedures. Completing work does not prove recovery.</p></div></div>${work.map(w=>workRow(w,canEdit)).join('')||'<div class="panelbody text-muted">No work items yet.</div>'}${canEdit&&i.scope!=='feed'?`<form id="work-form" class="panelbody"><div class="formgrid"><div class="field"><label for="work-template">Template</label><select id="work-template" name="template">${Object.entries(incident.data.templates||TEMPLATE_LABELS).map(([k,v])=>`<option value="${k}" ${suggestedTemplates[0]===k?'selected':''}>${esc(v.label||v)}${suggestedTemplates.includes(k)?' (suggested)':''}</option>`).join('')}</select></div><div class="field"><label for="work-station">Station</label><select id="work-station" name="station">${stations.map(s=>`<option>${esc(s)}</option>`).join('')}</select></div><div class="field"><label for="work-estimate">On-site estimate (minutes, blank = template default)</label><input id="work-estimate" name="estimateMinutes" type="number" min="0" max="720"></div><div class="field"><label for="work-assignee">Assignee</label><input id="work-assignee" name="assignee" maxlength="100" value="${esc(i.assignee||'')}"></div></div><button class="primary" type="submit">Create work item</button></form>`:''}</section>`;
 const shared=i.scope==='group'?`<div class="info"><strong>Before dispatching to every station:</strong> check the data service, then whether these stations share a modem, carrier, repeater or power feed. Fleet does not infer a shared cause. Visit the stations where remote checks fail, starting with the longest outage. Record the outcome as a remote-investigation work item.</div>`:'';
 const timeline=`<section class="panel"><div class="panelhead"><h2>Timeline</h2></div><ul class="timeline">${events.map(e=>`<li><span>${date(e.at)}</span><strong>${esc(e.type)}</strong> · ${esc(e.actor)}<p>${esc(e.detail)}</p></li>`).join('')}</ul></section>`;
 return `<button class="back" data-nav="review">← Daily review</button>`+header+shared+`<div class="detailgrid"><div>${reasons}${evidence}${group}${workPanel}</div><div>${form}${timeline}</div></div>`;
}
const TEMPLATE_LABELS={'remote-check':'Remote investigation','comms-power':'Communications / power investigation','sensor-inspection':'Sensor inspection','tower-sensor':'Tower-mounted sensor inspection','vegetation':'Vegetation / obstruction check','scheduled-service':'Scheduled service'};
function channelPill(s){const [k,l]=CHANNEL_STATE[s]||['unknown',s];return `<span class="pill ${k}">${esc(l)}</span>`;}
function workRow(w,canEdit){
 const tasks=w.confirmedTasks?.length?w.confirmedTasks:w.proposedTasks;
 return `<div class="queueitem work-row"><div class="grow"><div class="name">${esc(w.title)} <span class="pill ${w.status==='done'?'reporting':w.status==='cancelled'?'unknown':'delayed'}">${esc(w.status.replace('_',' '))}</span></div><p>${esc(w.station)} · ${w.estimateMinutes===null?'On-site time unknown':`${w.estimateMinutes} ± ${w.uncertaintyMinutes||0} min (${esc(w.estimateBasis)})`} · ${esc(w.taskClass)} · ${esc(w.assignee||'unassigned')}</p><details><summary>${w.confirmedTasks?.length?'Confirmed':'Proposed'} tasks (${tasks.length})</summary><ul class="plain">${tasks.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${w.parts?.length?`<p class="footnote">Parts: ${esc(w.parts.join(', '))}</p>`:''}${w.skills?.length?`<p class="footnote">Skills: ${esc(w.skills.join(', '))}</p>`:''}<p class="footnote">${esc(w.recoveryCriteria)}</p></details>${w.workPerformed?`<p><strong>Work performed:</strong> ${esc(w.workPerformed.summary)} (${esc(w.workPerformed.recordedBy)})</p>`:''}${canEdit&&!['done','cancelled'].includes(w.status)?`<form class="work-update" data-work="${esc(w.id)}" data-revision="${esc(w.revision)}"><select name="status" aria-label="Work status">${['proposed','confirmed','planned','in_progress','awaiting_parts','awaiting_access','done','cancelled'].map(s=>`<option ${s===w.status?'selected':''} value="${s}">${s.replace('_',' ')}</option>`).join('')}</select><input name="workPerformed" placeholder="Work actually performed (required for done)" maxlength="2000"><button class="small" type="submit">Save</button></form>`:''}</div><a class="linkbutton small" href="/field-notes/?work=${encodeURIComponent(w.id)}">Start Field Notes</a></div>`;
}
function groupPanel(i,members,canEdit,state){
 const others=(state.ops?.queue||[]).filter(q=>q.scope==='group'&&q.id!==i.id);
 return `<section class="panel"><div class="panelhead"><div><h2>Members</h2><p>${esc((i.body.reasons||[])[0]||'')}</p></div></div><div class="tablewrap"><table><thead><tr><th>Station</th><th>Membership</th><th>Station incident</th></tr></thead><tbody>${members.map(m=>`<tr><td><button class="station-link" data-station="${esc(m.id)}">${esc(m.id)}</button></td><td>${esc(m.status)}<small>Joined ${date(m.joinedAt)}${m.leftAt?' · left '+date(m.leftAt):''}</small></td><td>${m.incident?`<button class="station-link" data-incident="${esc(m.incident.id)}">${esc(m.incident.tier)} · ${esc(STATE_LABEL[m.incident.state]||m.incident.state)}</button><small>${esc(m.incident.telemetry)} · ${esc(m.incident.assignee||'unassigned')}</small>`:'—'}</td></tr>`).join('')}</tbody></table></div>${canEdit?`<details class="panelbody"><summary>Split or merge (audited)</summary><form id="split-form"><p class="footnote">Split stations out of this group. Fleet will not regroup them automatically.</p>${(i.body.stations||[]).map(s=>`<label class="check"><input type="checkbox" name="stations" value="${esc(s)}"> ${esc(s)}</label>`).join('')}<div class="field"><label for="split-mode">Mode</label><select id="split-mode" name="mode"><option value="standalone">Single-station incidents</option><option value="new-group">New separate group</option></select></div><div class="field"><label for="split-reason">Reason</label><input id="split-reason" name="reason" required maxlength="300"></div><button class="small" type="submit">Split</button></form>${others.length?`<form id="merge-form"><div class="field"><label for="merge-other">Merge another group into this one</label><select id="merge-other" name="otherId">${others.map(o=>`<option value="${esc(o.id)}" data-revision="${esc(o.revision)}">${esc(o.title)} (${esc(o.stations.join(', '))})</option>`).join('')}</select></div><div class="field"><label for="merge-reason">Reason</label><input id="merge-reason" name="reason" required maxlength="300"></div><button class="small" type="submit">Merge</button></form>`:''}</details>`:''}</section>`;
}
async function loadIncident(){const id=incident.id;incident.loading=true;try{const d=await api('ops/incidents/'+id);if(incident.id!==id)return;incident.data=d;incident.error='';}catch(e){if(incident.id===id)incident.error=e.message;}finally{if(incident.id===id){incident.loading=false;rerender();}}}
export function refreshIncident(){if(incident.id){incident.data=null;incident.error='';}}

// ---------- station sections ----------
export function stationOps(stationId,{canEdit}){
 if(station.id!==stationId)station={id:stationId,data:null,error:'',loading:false};
 if(!station.data&&!station.loading&&!station.error)queueMicrotask(loadStation);
 if(!station.data)return `<section class="panel"><div class="panelbody">${station.error?`<div class="alert error">${esc(station.error)}</div>`:'Loading sensor inventory, incidents and references…'}</div></section>`;
 const d=station.data,h=d.health,[rk,rl]=REPORTING[h.reporting]||['unknown',h.reporting];
 const open=d.incidents.filter(i=>i.state!=='resolved'&&i.state!=='merged');
 const inv=`<section class="panel"><div class="panelhead"><div><h2>Expected sensors vs reporting</h2><p><span class="pill ${rk}">${esc(rl)}</span> ${h.reportingCount}/${h.expectedCount} expected channels reporting · newest ${date(h.newest)} · assessed ${date(h.assessedAt)}</p></div></div>${h.reasons.length?`<div class="panelbody">${h.reasons.map(r=>`<p>${esc(r)}</p>`).join('')}</div>`:''}<div class="tablewrap"><table><thead><tr><th>Channel</th><th>Expected</th><th>State</th><th>Value</th><th>Observed ET</th><th>Instrument group</th>${canEdit?'<th></th>':''}</tr></thead><tbody>${h.channels.map(c=>{const p=d.profile.find(r=>r.channel===c.channel);return `<tr><td class="mono">${esc(c.channel)}<small>${esc(c.variable)}${c.position!==null&&c.position!==undefined?' · '+esc(c.position)+' m':''}</small></td><td>${esc(c.expectation)}<small>${esc(p?.source==='team'?'team-confirmed':'inferred')}</small></td><td>${channelPill(c.state)}<small>${esc(c.note)}</small></td><td><strong class="num">${num(c.value)}</strong> <span class="unit">${esc(c.unit||'')}</span></td><td>${date(c.time)}${Number.isFinite(c.lagMinutes)?`<small>${c.lagMinutes} min behind newest</small>`:''}</td><td>${esc(c.groupLabel)}${c.groupProvisional?'<small>provisional</small>':''}</td>${canEdit&&p?`<td><button class="small quiet" data-profile="${esc(c.channel)}" data-revision="${esc(p.revision)}" data-expected="${esc(p.expected)}">Edit</button></td>`:canEdit?'<td></td>':''}</tr>`;}).join('')}</tbody></table></div><p class="footnote panelbody">Expectations are bootstrapped from metadata and coverage. Channels never reported, dormant at bootstrap or marked removed/seasonal do not raise faults. A channel that was expected stays expected when it disappears.</p></section>`;
 const inc=`<section class="panel"><div class="panelhead"><h2>Incidents</h2></div>${d.incidents.map(i=>`<div class="queueitem"><div class="grow"><div class="name">${tierPill(i.tierOverride?.tier||i.tier,{confidence:i.confidence})} <span class="pill">${esc(STATE_LABEL[i.state]||i.state)}</span></div><p>${esc((i.body.reasons||[])[0]||'')}</p><p>${date(i.created)}${i.resolvedAt?' → '+date(i.resolvedAt):''}</p></div><button class="small" data-incident="${esc(i.id)}">Open</button></div>`).join('')||'<div class="panelbody text-muted">No incidents recorded.</div>'}</section>`;
 const work=`<section class="panel"><div class="panelhead"><h2>Maintenance history</h2></div>${d.work.map(w=>workRow(w,false)).join('')||'<div class="panelbody text-muted">No work items.</div>'}</section>`;
 return inv+`<div class="detailgrid"><div>${coveragePanel(d,canEdit)}</div><div>${inc}${notesPanel(d,canEdit)}${work}</div></div>`;
}
function coveragePanel(d,canEdit){
 const c=d.coverage,activeOverrides=d.overrides.filter(o=>!o.removed_at);
 return `<section class="panel"><div class="panelhead"><div><h2>Nearby reference coverage</h2><p>${esc(c.method)}</p></div></div><div class="tablewrap"><table><thead><tr><th>Variable</th><th>Coverage</th><th>Target</th><th>Reference band</th><th>References</th></tr></thead><tbody>${c.rows.map(r=>`<tr><td>${esc(r.label)}${r.position!==null&&r.position!==undefined?`<small>${esc(r.position)} m</small>`:''}</td><td><span class="pill ${r.status==='available'?'reporting':r.status==='not-applicable'?'unknown':'delayed'}">${esc(r.status.replace(/-/g,' '))}</span><small>${esc(r.reason)}</small></td><td>${r.target?`${num(r.target.value)} ${esc(r.unit||'')}<small>${date(r.target.time)}</small>`:'—'}</td><td>${r.band?`${r.band.circular?'mean':'median'} ${num(r.band.median)} ± ${num(r.band.tolerance)}<small>${r.residual===null||r.residual===undefined?'No residual':`residual ${num(r.residual)} · ${r.inBand?'inside':'outside'} band`}</small>`:'—'}</td><td>${(r.references||[]).map(x=>`${esc(x.name)} <small>${x.distanceKm} km · ${num(x.value)} at ${date(x.time)}${x.pinned?' · pinned':''}</small>`).join('')||'—'}${r.excluded?.length?`<details><summary>${r.excluded.length} excluded</summary>${r.excluded.slice(0,12).map(x=>`<small>${esc(x.name)} (${x.distanceKm} km): ${esc(x.reason)}</small>`).join('')}</details>`:''}${r.warnings?.length?`<small class="qc-note">${esc(r.warnings.join(' '))}</small>`:''}</td></tr>`).join('')}</tbody></table></div><div class="panelbody"><p class="footnote">Reference statistics are investigation evidence, not certified ground truth. Neighbour values never replace target observations; insufficient coverage stays unavailable.</p>${activeOverrides.length?`<h3>Team overrides</h3>${activeOverrides.map(o=>`<p>${esc(o.action)} ${esc(o.reference)} for ${esc(o.variable)} — ${esc(o.reason)} (${esc(o.actor)}, ${date(o.at)}) ${canEdit?`<button class="small quiet" data-remove-override="${esc(o.id)}">Remove</button>`:''}</p>`).join('')}`:''}${canEdit?`<details><summary>Pin or exclude a reference</summary><form id="override-form" class="formgrid"><div class="field"><label for="ov-variable">Variable</label><select id="ov-variable" name="variable">${c.rows.filter((r,i,a)=>a.findIndex(x=>x.variable===r.variable)===i).map(r=>`<option value="${esc(r.variable)}">${esc(r.label)}</option>`).join('')}</select></div><div class="field"><label for="ov-reference">Reference station ID</label><input id="ov-reference" name="reference" required maxlength="100" list="station-ids"></div><div class="field"><label for="ov-action">Action</label><select id="ov-action" name="action"><option value="exclude">Exclude</option><option value="pin">Pin</option></select></div><div class="field"><label for="ov-reason">Reason</label><input id="ov-reason" name="reason" required maxlength="500"></div><button class="small" type="submit">Save override</button></form></details>`:''}</div></section>`;
}
function windowsText(ws){const D=['','Mon','Tue','Wed','Thu','Fri','Sat','Sun'];return (ws||[]).map(w=>`${w.days.map(d=>D[d]).join(',')} ${w.start}-${w.end}`).join('; ');}
export function parseWindows(text){
 if(!text.trim())return null;const D={mon:1,tue:2,wed:3,thu:4,fri:5,sat:6,sun:7};
 return text.split(';').map(part=>{const m=part.trim().match(/^([A-Za-z,\- ]+)\s+(\d{1,2}:\d{2})\s*-\s*(\d{1,2}:\d{2})$/);if(!m)throw Error('Write access windows like "Mon-Fri 08:00-16:00; Sat 09:00-12:00".');const days=new Set();for(const tok of m[1].toLowerCase().split(',').map(s=>s.trim()).filter(Boolean)){const r=tok.split('-').map(s=>D[s.slice(0,3)]);if(r.some(x=>!x))throw Error('Unknown weekday in access windows.');if(r.length===2){for(let d=r[0];d!==r[1];d=d%7+1)days.add(d);days.add(r[1]);}else days.add(r[0]);}const pad=t=>t.padStart(5,'0');return {days:[...days].sort(),start:pad(m[2]),end:pad(m[3])};});
}
function notesPanel(d,canEdit){
 const n=d.notes||{};
 if(!canEdit)return `<section class="panel"><div class="panelhead"><h2>Access</h2></div><div class="panelbody"><dl class="definition"><dt>Access notes</dt><dd>${esc(n.accessNotes||'Not recorded')}</dd><dt>Gate code</dt><dd>${n.gateCodeRestricted?'Restricted to editors':esc(n.gateCode||'Not recorded')}</dd><dt>Road entrance</dt><dd>${n.entrance?`${n.entrance.lat}, ${n.entrance.lon}`:'Unknown — routes to station coordinates'}</dd><dt>Access windows</dt><dd>${esc(windowsText(n.accessWindows)||'Unknown')}</dd><dt>Region</dt><dd>${esc(n.region||'—')}</dd><dt>Planned maintenance</dt><dd>${n.maintenance?`${date(n.maintenance.from)} – ${date(n.maintenance.until)}: ${esc(n.maintenance.reason)}`:'None'}</dd></dl></div></section>`;
 return `<section class="panel"><div class="panelhead"><div><h2>Access & site notes</h2><p>Private to the team. Gate codes are hidden from viewers and never placed in links or offline packets.</p></div></div><form id="notes-form" class="panelbody" data-revision="${esc(n.revision||'')}"><div class="field"><label for="n-access">Access notes</label><textarea id="n-access" name="accessNotes" maxlength="4000">${esc(n.accessNotes||'')}</textarea></div><div class="formgrid"><div class="field"><label for="n-gate">Gate code</label><input id="n-gate" name="gateCode" maxlength="100" autocomplete="off" value="${esc(n.gateCode||'')}"></div><div class="field"><label for="n-region">Region</label><input id="n-region" name="region" maxlength="60" value="${esc(n.region||'')}"></div><div class="field"><label for="n-elat">Road entrance latitude</label><input id="n-elat" name="entranceLat" inputmode="decimal" value="${esc(n.entrance?.lat??'')}"></div><div class="field"><label for="n-elon">Road entrance longitude</label><input id="n-elon" name="entranceLon" inputmode="decimal" value="${esc(n.entrance?.lon??'')}"></div><div class="field wide"><label for="n-windows">Access windows</label><input id="n-windows" name="accessWindows" placeholder="Mon-Fri 08:00-16:00" value="${esc(windowsText(n.accessWindows))}"></div><div class="field"><label for="n-importance">Operational importance</label><select id="n-importance" name="importance">${[0,1,2,3].map(v=>`<option ${Number(n.importance||0)===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="n-deps">Known shared dependencies</label><input id="n-deps" name="dependencies" placeholder="e.g. repeater-north" value="${esc((n.dependencies||[]).join(', '))}"></div><div class="field"><label for="n-mfrom">Planned maintenance from</label><input id="n-mfrom" name="maintFrom" type="datetime-local" value="${esc(n.maintenance?.from?toLocalInput(n.maintenance.from):'')}"></div><div class="field"><label for="n-muntil">until</label><input id="n-muntil" name="maintUntil" type="datetime-local" value="${esc(n.maintenance?.until?toLocalInput(n.maintenance.until):'')}"></div><div class="field wide"><label for="n-mreason">Maintenance reason</label><input id="n-mreason" name="maintReason" maxlength="300" value="${esc(n.maintenance?.reason||'')}"></div><div class="field wide"><label for="n-hazards">Hazards / parking / contacts</label><textarea id="n-hazards" name="hazards" maxlength="2000">${esc(n.hazards||'')}</textarea></div></div><button class="primary" type="submit">Save notes</button><p class="footnote">${n.updated?`Updated ${date(n.updated)} by ${esc(n.updatedBy)}`:'Not recorded yet. Unknown access stays unknown in plans.'}</p></form></section>`;
}
const toLocalInput=iso=>{const d=new Date(iso),p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'America/Detroit',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(d).map(x=>[x.type,x.value]));return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}`;};
async function loadStation(){const id=station.id;station.loading=true;try{const d=await api('ops/stations/'+encodeURIComponent(id));if(station.id!==id)return;station.data=d;station.error='';}catch(e){if(station.id===id)station.error=e.message;}finally{if(station.id===id){station.loading=false;rerender();}}}
export function refreshStation(){if(station.id){station.data=null;station.error='';}}

// ---------- binding ----------
export function bindOps(ctx){
 ({api,toast,rerender}=ctx);currentUser=ctx.state.user;const root=document;
 root.querySelectorAll('[data-queue-filter]').forEach(el=>{const key=el.dataset.queueFilter;el[key==='search'?'oninput':'onchange']=e=>{filters[key]=e.target.value;const body=document.querySelector('#queue-rows');if(body){const ops=ctx.state.ops,items=visible(ops),lim=Number(body.dataset.limit)||Infinity;body.innerHTML=items.slice(0,lim).map(i=>row(i)).join('')||'<tr><td colspan="7"><div class="empty">No items match these filters.</div></td></tr>';document.querySelector('#queue-count').textContent=`${items.length} of ${ops.queue.length}`;bindRows(ctx);}};});
 root.querySelectorAll('[data-tier-filter]').forEach(b=>b.onclick=()=>{filters.tier=filters.tier===b.dataset.tierFilter?'all':b.dataset.tierFilter;ctx.setView('review');});
 bindRows(ctx);
 if(root.querySelector('#download-queue'))root.querySelector('#download-queue').onclick=()=>ctx.download({schemaVersion:1,kind:'enviroweather-fleet-queue',exportedAt:new Date().toISOString(),networkFetchedAt:ctx.state.ops.feed.networkFetchedAt,versions:ctx.state.ops.versions,counts:ctx.state.ops.counts,tieBreakers:ctx.state.ops.tieBreakers,queue:ctx.state.ops.queue},'fleet-queue.json');
 root.querySelectorAll('[data-ack]').forEach(b=>b.onclick=async()=>{try{await api('ops/alerts/ack',{method:'POST',body:JSON.stringify({ids:[b.dataset.ack]})});alerts.data=null;await ctx.reload();}catch(e){toast(e.message);}});
 if(root.querySelector('#ack-all'))root.querySelector('#ack-all').onclick=async()=>{try{await api('ops/alerts/ack',{method:'POST',body:JSON.stringify({ids:(alerts.data?.alerts||[]).map(a=>a.id)})});alerts.data=null;await ctx.reload();}catch(e){toast(e.message);}};
 root.querySelectorAll('[data-plan-stations]').forEach(b=>b.onclick=()=>ctx.openPlanner({required:b.dataset.planStations.split(',').filter(Boolean)}));
 bindIncident(ctx);bindStation(ctx);
}
function bindRows(ctx){
 document.querySelectorAll('[data-incident]').forEach(b=>b.onclick=e=>{e.stopPropagation();ctx.openIncident(b.dataset.incident);});
 document.querySelectorAll('#queue-rows [data-station]').forEach(b=>b.onclick=e=>{e.stopPropagation();ctx.openStation(b.dataset.station);});
 document.querySelectorAll('[data-expand]').forEach(b=>b.onclick=e=>{e.stopPropagation();const id=b.dataset.expand;expanded.has(id)?expanded.delete(id):expanded.add(id);rerender();});
 document.querySelectorAll('[data-locate]').forEach(b=>b.onclick=e=>{e.stopPropagation();const tr=b.closest('tr');selectedItem=tr.dataset.queueItem;document.querySelectorAll('.queue-row.selected').forEach(r=>r.classList.remove('selected'));tr.classList.add('selected');mapApi?.focus(tr.dataset.stations.split(',').filter(Boolean));});
}
function bindIncident(ctx){
 const form=document.querySelector('#incident-form');
 if(form){
  const capture=()=>{incident.form=Object.fromEntries(new FormData(form));};
  form.oninput=()=>{capture();document.querySelector('#resolution-field').hidden=form.state.value!=='resolved'||incident.data.incident.state==='resolved';};
  const send=async patch=>{const i=incident.data.incident;try{await api('ops/incidents/'+i.id,{method:'PATCH',body:JSON.stringify({revision:i.revision,...patch})});incident.form=null;incident.data=null;incident.error='';toast('Incident updated.');await ctx.reload();}catch(e){incident.error=e.status===409?e.message:e.message;document.querySelector('#incident-message').innerHTML=esc(e.message)+(e.status===409?' <button type="button" class="small" id="reload-incident">Reload latest</button>':'');const r=document.querySelector('#reload-incident');if(r)r.onclick=()=>{incident.data=null;incident.error='';rerender();};}};
  form.onsubmit=e=>{e.preventDefault();capture();const f=incident.form,i=incident.data.incident,patch={};
   if((f.assignee||'')!==(i.assignee||''))patch.assignee=f.assignee||null;
   if(f.state!==i.state){patch.state=f.state;if(f.state==='resolved')patch.resolutionReason=f.resolutionReason;}
   if((f.tier||'')!==(i.tierOverride?.tier||'')||(f.tier&&f.tierReason!==(i.tierOverride?.reason||'')))patch.tierOverride=f.tier?{tier:f.tier,reason:f.tierReason}:null;
   if((f.deferUntil||'')!==((i.deferral?.until||'').slice(0,10))||(f.deferUntil&&f.deferReason!==(i.deferral?.reason||'')))patch.deferral=f.deferUntil?{until:detroit(f.deferUntil,'23:59'),reason:f.deferReason}:null;
   if(f.note)patch.note=f.note;
   send(patch);};
  const ack=document.querySelector('#inc-ack');if(ack)ack.onclick=()=>{capture();send({acknowledge:true,...(incident.form.assignee&&incident.form.assignee!==incident.data.incident.assignee?{assignee:incident.form.assignee}:{})});};
 }
 const work=document.querySelector('#work-form');
 if(work)work.onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(work));try{await api('ops/work',{method:'POST',body:JSON.stringify({incidentId:incident.data.incident.id,station:f.station,template:f.template,assignee:f.assignee||undefined,...(f.estimateMinutes?{estimateMinutes:Number(f.estimateMinutes)}:{})})});incident.data=null;toast('Work item created (proposed).');rerender();}catch(err){toast(err.message);}};
 document.querySelectorAll('.work-update').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(f));try{await api('ops/work/'+f.dataset.work,{method:'PATCH',body:JSON.stringify({revision:f.dataset.revision,status:v.status,...(v.workPerformed?{workPerformed:{summary:v.workPerformed}}:{})})});incident.data=null;station.data=null;toast(v.status==='done'?'Work recorded. Recovery is verified from telemetry.':'Work item updated.');rerender();}catch(err){toast(err.message);}});
 const split=document.querySelector('#split-form');
 if(split)split.onsubmit=async e=>{e.preventDefault();const i=incident.data.incident,f=new FormData(split);try{await api(`ops/incidents/${i.id}/split`,{method:'POST',body:JSON.stringify({revision:i.revision,stations:f.getAll('stations'),mode:f.get('mode'),reason:f.get('reason')})});incident.data=null;toast('Group split. The change is in the timeline.');await ctx.reload();}catch(err){toast(err.message);}};
 const merge=document.querySelector('#merge-form');
 if(merge)merge.onsubmit=async e=>{e.preventDefault();const i=incident.data.incident,sel=merge.otherId;try{await api(`ops/incidents/${i.id}/merge`,{method:'POST',body:JSON.stringify({revision:i.revision,otherId:sel.value,otherRevision:sel.selectedOptions[0].dataset.revision,reason:merge.reason.value})});incident.data=null;toast('Groups merged.');await ctx.reload();}catch(err){toast(err.message);}};
}
function bindStation(ctx){
 const notes=document.querySelector('#notes-form');
 if(notes)notes.onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(notes));try{const body={revision:notes.dataset.revision||null,accessNotes:f.accessNotes,gateCode:f.gateCode,region:f.region,importance:Number(f.importance),hazards:f.hazards,accessWindows:parseWindows(f.accessWindows),dependencies:f.dependencies.split(',').map(s=>s.trim()).filter(Boolean),entrance:f.entranceLat&&f.entranceLon?{lat:Number(f.entranceLat),lon:Number(f.entranceLon)}:null,maintenance:f.maintFrom&&f.maintUntil?{from:detroit(...f.maintFrom.split('T')),until:detroit(...f.maintUntil.split('T')),reason:f.maintReason}:null};await api('ops/notes/'+encodeURIComponent(station.id),{method:'PUT',body:JSON.stringify(body)});station.data=null;toast('Station notes saved.');rerender();}catch(err){toast(err.message);}};
 document.querySelectorAll('[data-profile]').forEach(b=>b.onclick=()=>{const d=document.querySelector('#recordDialog');d.innerHTML=`<form id="profile-form"><h2>Sensor expectation · ${esc(b.dataset.profile)}</h2><p>Changing expectations changes which missing channels raise incidents. The change and reason are recorded on any open incident.</p><div class="field"><label for="pf-expected">Expectation</label><select id="pf-expected" name="expected">${['expected','optional','seasonal','removed','not-expected'].map(v=>`<option ${v===b.dataset.expected?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="pf-months">Seasonal months (1–12, comma separated)</label><input id="pf-months" name="months" placeholder="4,5,6,7,8,9,10"></div><div class="field"><label for="pf-removed">Removal date (optional)</label><input id="pf-removed" name="removed" type="date"></div><div class="field"><label for="pf-reason">Reason</label><input id="pf-reason" name="reason" required maxlength="300"></div><div class="actions"><button type="button" id="pf-cancel">Cancel</button><button class="primary" type="submit">Save</button></div></form>`;d.showModal();d.querySelector('#pf-cancel').onclick=()=>d.close();d.querySelector('#profile-form').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target));try{await api(`ops/profiles/${encodeURIComponent(station.id)}/${encodeURIComponent(b.dataset.profile)}`,{method:'PATCH',body:JSON.stringify({revision:b.dataset.revision,expected:f.expected,reason:f.reason,...(f.expected==='seasonal'?{seasonal:{months:f.months.split(',').map(Number).filter(Boolean)}}:{}),...(f.removed?{removed:f.removed+'T00:00:00Z'}:{})})});d.close();station.data=null;toast('Sensor expectation saved.');rerender();}catch(err){toast(err.message);}};});
 const ov=document.querySelector('#override-form');
 if(ov)ov.onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(ov));try{await api('ops/reference-overrides',{method:'POST',body:JSON.stringify({station:station.id,...f})});station.data=null;toast('Reference override saved.');rerender();}catch(err){toast(err.message);}};
 document.querySelectorAll('[data-remove-override]').forEach(b=>b.onclick=async()=>{const reason=prompt('Why remove this override?');if(!reason)return;try{await api(`ops/reference-overrides/${b.dataset.removeOverride}/remove`,{method:'POST',body:JSON.stringify({reason})});station.data=null;rerender();}catch(err){toast(err.message);}});
}

// ---------- fleet settings (Connections page) ----------
let fleetCfg={data:null,loading:false,error:''};
export function fleetSettingsPanel(){
 if(!fleetCfg.data&&!fleetCfg.loading&&!fleetCfg.error){fleetCfg.loading=true;api('ops/settings').then(s=>{fleetCfg.data=s;}).catch(e=>{fleetCfg.error=e.message;}).finally(()=>{fleetCfg.loading=false;rerender();});}
 const s=fleetCfg.data,owner=currentUser?.role==='owner';
 if(!s)return `<section class="panel"><div class="panelbody">${fleetCfg.error?`<div class="alert error">${esc(fleetCfg.error)}</div>`:'Loading fleet settings…'}</div></section>`;
 const r=s.routing,f=s.fleet,g=f.grouping,dis=owner?'':'disabled';
 const input=(name,val,attrs='')=>`<input name="${name}" value="${esc(val)}" ${attrs} ${dis}>`;
 return `<section class="panel"><div class="panelhead"><div><h2>Road routing</h2><p>${esc(r.attribution)}</p></div><span class="pill ${r.configured?'reporting':'unknown'}">${r.configured?'Configured':'Setup needed'}</span></div><div class="panelbody"><p>${r.configured?`OpenRouteService ${esc(r.profile)} · no departure-time traffic model · up to ${r.limits.maxMatrixPoints} points per matrix.`:esc(r.setup)}</p><p class="footnote">${esc(r.limits.plan)}: ${r.limits.matrixPerDay} matrix and ${r.limits.directionsPerDay} route requests per day. Matrices and routes are cached 24 hours; planning is limited to 60 requests per user per hour. Google Routes was not used: its terms prohibit display on this app's non-Google map and caching of durations.</p><h3>Forecasts</h3><p>National Weather Service gridpoint forecasts and active Michigan alerts (no account). Grids are cached for one hour, alerts for five minutes. Rainfall amounts are forecast about 3 days ahead; beyond that they are unknown.</p></div></section>
 <section class="panel"><div class="panelhead"><div><h2>Incident and planning policy</h2><p>${owner?'Owner only. Changes apply from the next snapshot.':'Set by the owner.'} ${s.updated?`Updated ${date(s.updated)} by ${esc(s.updatedBy)}.`:'Provisional defaults; not yet reviewed by the team.'}</p></div></div><form id="fleet-settings-form" class="panelbody"><div class="formgrid three"><div class="field"><label>Confirm outage after new snapshots</label>${input('outageConfirmCount',f.outageConfirmCount,'type="number" min="1" max="8"')}</div><div class="field"><label>Confirm recovery after new snapshots</label>${input('recoveryConfirmCount',f.recoveryConfirmCount,'type="number" min="1" max="8"')}</div><div class="field"><label>Confirm sensor issue after new snapshots</label>${input('sensorConfirmCount',f.sensorConfirmCount,'type="number" min="1" max="12"')}</div><div class="field"><label>Channel lag limit (minutes)</label>${input('channelLagMinutes',f.channelLagMinutes,'type="number" min="30" max="1440"')}</div><div class="field"><label>Group link distance (km)</label>${input('linkKm',g.linkKm,'type="number" min="5" max="150"')}</div><div class="field"><label>Group maximum span (km)</label>${input('maxDiameterKm',g.maxDiameterKm,'type="number" min="5" max="400"')}</div><div class="field"><label>Group onset window (minutes)</label>${input('onsetWindowMinutes',g.onsetWindowMinutes,'type="number" min="15" max="1440"')}</div><div class="field"><label>Provider-problem threshold (fraction fresh)</label>${input('massOutageFraction',f.massOutageFraction,'type="number" min="0.1" max="0.9" step="0.05"')}</div><div class="field"><label>Response deadlines P1/P2/P3/P4 (hours)</label>${input('deadlines',['P1','P2','P3','P4'].map(k=>s.deadlines[k]).join('/'))}</div></div><h3>Task-weather rules</h3><p class="footnote">Provisional rules only produce cautions. Mark a class adopted when the team approves it; adopted rules become hard planning constraints. ${esc('Generic forecasts cannot certify lightning absence or field safety.')}</p><div class="tablewrap"><table><thead><tr><th>Task class</th><th>Max rain chance %</th><th>Max gust m/s</th><th>Max wind m/s</th><th>Min / max °C</th><th>Max thunder %</th><th>Daylight</th><th>Adopted</th></tr></thead><tbody>${Object.entries(s.rules).map(([k,v])=>`<tr><td>${esc(s.taskClasses[k].label)}</td><td>${input(`r-${k}-maxPop`,v.maxPop,'type="number" min="0" max="100"')}</td><td>${input(`r-${k}-maxGustMs`,v.maxGustMs,'type="number" min="0" max="60" step="0.1"')}</td><td>${input(`r-${k}-maxWindMs`,v.maxWindMs,'type="number" min="0" max="60" step="0.1"')}</td><td>${input(`r-${k}-minTempC`,v.minTempC,'type="number" min="-50" max="30" style="width:70px"')} ${input(`r-${k}-maxTempC`,v.maxTempC,'type="number" min="0" max="50" style="width:70px"')}</td><td>${input(`r-${k}-maxThunderPct`,v.maxThunderPct,'type="number" min="0" max="100"')}</td><td><input type="checkbox" name="r-${k}-daylight" ${v.daylight?'checked':''} ${dis}></td><td><input type="checkbox" name="r-${k}-adopted" ${v.adopted?'checked':''} ${dis}>${v.adopted?`<small>${esc(v.adoptedBy||'')}</small>`:''}</td></tr>`).join('')}</tbody></table></div><h3>Base locations</h3><div class="field"><label for="fs-bases">One per line: label, latitude, longitude</label><textarea id="fs-bases" name="bases" ${dis}>${esc((s.planner.bases||[]).map(b=>`${b.label}, ${b.lat}, ${b.lon}`).join('\n'))}</textarea></div>${owner?'<button class="primary" type="submit">Save policy</button>':''}<p class="footnote">${esc(GROUPING_NOTE)}</p></form></section>`;
}
const GROUPING_NOTE='Grouping defaults come from fleet spacing (median nearest neighbour 15 km, 90th percentile 36 km) and hourly reporting. A group never implies a shared cause.';
export function bindFleetSettings(ctx){
 const form=document.querySelector('#fleet-settings-form');if(!form||currentUser?.role!=='owner')return;
 form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form),n=k=>Number(f.get(k)),s=fleetCfg.data;try{
  const [P1,P2,P3,P4]=String(f.get('deadlines')).split('/').map(Number);
  const rules=Object.fromEntries(Object.keys(s.rules).map(k=>[k,{...s.rules[k],maxPop:n(`r-${k}-maxPop`),maxGustMs:n(`r-${k}-maxGustMs`),maxWindMs:n(`r-${k}-maxWindMs`),minTempC:n(`r-${k}-minTempC`),maxTempC:n(`r-${k}-maxTempC`),maxThunderPct:n(`r-${k}-maxThunderPct`),daylight:f.get(`r-${k}-daylight`)==='on',adopted:f.get(`r-${k}-adopted`)==='on',adoptedBy:f.get(`r-${k}-adopted`)==='on'?(s.rules[k].adopted?s.rules[k].adoptedBy:currentUser.name):null}]));
  const bases=String(f.get('bases')).split('\n').map(l=>l.trim()).filter(Boolean).map(l=>{const p=l.split(',').map(x=>x.trim());return {label:p[0],lat:Number(p[1]),lon:Number(p[2])};});
  fleetCfg.data=await api('ops/settings',{method:'POST',body:JSON.stringify({fleet:{outageConfirmCount:n('outageConfirmCount'),recoveryConfirmCount:n('recoveryConfirmCount'),sensorConfirmCount:n('sensorConfirmCount'),channelLagMinutes:n('channelLagMinutes'),massOutageFraction:n('massOutageFraction'),grouping:{linkKm:n('linkKm'),maxDiameterKm:n('maxDiameterKm'),onsetWindowMinutes:n('onsetWindowMinutes')}},deadlines:{P1,P2,P3,P4},rules,planner:{...s.planner,bases}})});
  fleetCfg.data.routing=s.routing;fleetCfg.data.taskClasses=s.taskClasses;toast('Fleet policy saved.');rerender();
 }catch(err){toast(err.message);}};
}
export function resetFleetSettings(){fleetCfg={data:null,loading:false,error:''};}
